const main = document.querySelector('#main');
const modal = document.querySelector('#modal');
const toastNode = document.querySelector('#toast');
const labels = { home:'Обзор', wardrobe:'Мой гардероб', stylist:'Стилист', outfits:'Мои образы', shopping:'Покупки', favorites:'Избранное', calendar:'Календарь', settings:'Настройки' };
let state = emptyState();
let page = 'home';
let database = null;
let storageMode = 'loading';
let storageIssue = '';
let toastTimer;
let previousFocus;
let dialogNavigation = false;
let dialogReturn = null;
let shoppingFilter = 'planned';
let submitting = false;
let searchTimer;
let filters = { query:'',category:'',color:'',season:'',availability:'' };
let displayedMonth = new Date(new Date().getFullYear(),new Date().getMonth(),1);
let selectedDate = localDate();
let stylistCriteria = {occasion:'everyday',style:'any',season:'',date:localDate(),anchorItemId:'',weatherMode:'auto',feelsLike:'',rainProbability:'',windSpeed:''};
let stylistResult = null;
let stylistVariant = 0;
let stylistBusy = false;
let stylistRequest = 0;
const weatherCache = new Map();
const weatherPending = new Map();
const esc = value => String(value ?? '').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icon = name => `<svg class="icon" aria-hidden="true"><use href="#icon-${name}"></use></svg>`;
const plural = (n,one,few,many) => `${n} ${n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many}`;
const dateLabel = value => validDate(value)?new Date(`${value}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}):'Выберите дату';
const button = (action,label,classes='btn btn-secondary',id='',glyph='') => `<button type="button" class="${classes}" data-action="${action}"${id?` data-id="${esc(id)}"`:''}>${glyph?icon(glyph):''}${esc(label)}</button>`;
function toast(message,error=false) { clearTimeout(toastTimer); toastNode.textContent=message; toastNode.className=`toast is-visible${error?' is-error':''}`; toastNode.setAttribute('role',error?'alert':'status'); toastTimer=setTimeout(()=>{toastNode.className='toast';},5500); }
function formError(error) { const target=modal.querySelector('#form-error'); if(target) { target.textContent=error.message || String(error); target.hidden=false; } else toast(error.message || String(error),true); }
function storageWarning() { return storageMode==='memory' ? `<div class="notice error-notice" role="status">${icon('image')}<div><strong>Сейчас данные хранятся только до закрытия страницы.</strong><br>${esc(storageIssue)} Сохраните резервную копию в настройках.</div></div>` : ''; }
function changePage(next) { if(!Object.hasOwn(labels,next)) return; if(modal.open){dialogNavigation=true;modal.close();} page=next; render(); main.focus({preventScroll:true}); window.scrollTo({top:0,behavior:'instant'}); }
function openDialog(content) { if(!modal.open) previousFocus=document.activeElement; modal.innerHTML=content; modal.setAttribute('aria-labelledby','modal-title'); if(!modal.open) modal.showModal(); setTimeout(()=>modal.querySelector('[autofocus], input:not([type="checkbox"]):not([type="file"]), select, button')?.focus(),0); }
function closeDialog() { modal.close(); }
modal.addEventListener('close',()=>{ modal.innerHTML=''; if(dialogNavigation){dialogNavigation=false;dialogReturn=null;main.focus({preventScroll:true});return;} if(dialogReturn){const resume=dialogReturn;dialogReturn=null;resume();return;} if(previousFocus?.isConnected) previousFocus.focus(); else { const action=previousFocus?.dataset?.action; const id=previousFocus?.dataset?.id; const match=action?document.querySelector('[data-action=' + JSON.stringify(action) + ']' + (id?'[data-id=' + JSON.stringify(id) + ']':'')):null; (match || document.querySelector('#add-item') || main).focus(); } });
modal.addEventListener('click',event=>{ if(event.target===modal) { const rect=modal.getBoundingClientRect(); if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom) closeDialog(); } });
function dialog(title,subtitle,body,submit='Сохранить',formId='modal-form') { return `<form id="${formId}" class="modal-form"><div class="modal-header"><div><p class="eyebrow">MYCLOSET</p><h2 id="modal-title">${esc(title)}</h2>${subtitle?`<p class="subtitle">${esc(subtitle)}</p>`:''}</div><button class="icon-btn" type="button" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}<p id="form-error" class="form-error" role="alert" hidden></p></div><div class="form-actions"><button type="button" class="btn btn-secondary" data-action="close-dialog">Отмена</button><button class="btn btn-primary" type="submit">${esc(submit)}</button></div></form>`; }
function confirmDialog(title,message,onConfirm,label='Удалить') { openDialog(dialog(title,'',`<p>${esc(message)}</p>`,label,'confirm-form')); modal.querySelector('form').addEventListener('submit',event=>{event.preventDefault(); runSubmission(event.currentTarget,async()=>{await onConfirm(); closeDialog();});}); }
async function runSubmission(form,fn) { if(submitting) return; submitting=true; const submit=form.querySelector('[type="submit"]'); const original=submit?.textContent; if(submit){submit.disabled=true;submit.textContent='Сохраняем…';} try { await fn(); } catch(error) { formError(error); } finally { submitting=false; if(submit?.isConnected){submit.disabled=false;submit.textContent=original;} } }
function requestResult(request) { return new Promise((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error || new Error('Не удалось прочитать данные.'));}); }
async function initializeStorage() {
  try {
    if(!globalThis.indexedDB) throw new Error('Браузер не поддерживает локальное хранилище.');
    const request=indexedDB.open('mycloset-local-v1',1);
    request.onupgradeneeded=()=>request.result.createObjectStore('data');
    const timeout=new Promise((_,reject)=>setTimeout(()=>reject(new Error('Браузер не разрешил открыть хранилище.')),4500));
    database=await Promise.race([requestResult(request),timeout]);
    database.onversionchange=()=>{database.close();database=null;storageMode='memory';storageIssue='Хранилище обновлено в другой вкладке. Перезагрузите страницу.';render();};
    const data=await requestResult(database.transaction('data','readonly').objectStore('data').get('state'));
    if(data) state=validateState(data);
    storageMode='persistent';
  } catch(error) { database?.close();database=null;storageMode='memory';storageIssue=error.message || 'Локальное хранилище недоступно.'; }
}
async function reopenForReset() {
 if(database || !globalThis.indexedDB) return;
 try { const request=indexedDB.open('mycloset-local-v1',1); request.onupgradeneeded=()=>request.result.createObjectStore('data'); database=await Promise.race([requestResult(request),new Promise((_,reject)=>setTimeout(()=>reject(new Error('Хранилище недоступно.')),4500))]); storageMode='persistent'; storageIssue=''; } catch { database=null; }
}
async function commit(next,message='') {
  const validated=validateState(next);
  if(database) await new Promise((resolve,reject)=>{ const transaction=database.transaction('data','readwrite'); transaction.objectStore('data').put(validated,'state'); transaction.oncomplete=resolve; transaction.onerror=()=>reject(new Error(transaction.error?.name==='QuotaExceededError'?'Не хватает места. Уменьшите фотографии или сохраните резервную копию. Изменения не сохранены.':'Не удалось сохранить изменения. Проверьте доступ к хранилищу браузера.')); transaction.onabort=()=>reject(new Error('Сохранение прервано. Изменения не сохранены.')); });
  const changedWardrobe=JSON.stringify(state.items)!==JSON.stringify(validated.items)||JSON.stringify(state.profile.location)!==JSON.stringify(validated.profile.location);state=validated;if(changedWardrobe){stylistResult=null;stylistRequest++;}render(); if(message) toast(message + (storageMode==='memory'?' (до закрытия страницы)':''));
}
function cloneState() { return JSON.parse(JSON.stringify(state)); }

function clothingArt(item) {
  const color=COLORS[item.colors?.[0]]?.[1] || '#cfbba4'; const fill=color.startsWith('#')?color:'#b995ac';
  let shape='';
  if(item.category==='top') shape='<path d="M78 46 102 35q18 17 36 0l24 11 29 42-27 17-12-18v87H88V87l-12 18-27-17z"/><path d="M102 35q1 27 18 27t18-27" fill="none" stroke="#fff" stroke-opacity=".5" stroke-width="4"/>';
  if(item.category==='bottom') shape='<path d="M82 37h76l9 139h-34l-13-91-13 91H73z"/><path d="M84 56h72M120 39v42" fill="none" stroke="#fff" stroke-opacity=".4" stroke-width="3"/>';
  if(item.category==='dress') shape='<path d="m101 30 19 12 19-12 15 34-18 25 37 94H67l37-94-18-25z"/><path d="M104 89h32" fill="none" stroke="#fff" stroke-opacity=".6" stroke-width="4"/>';
  if(item.category==='outerwear') shape='<path d="m96 32 24 11 24-11 21 18 17 119-30 4-8-75v91H96V98l-8 75-30-4L75 50z"/><path d="m96 32 24 41 24-41M120 73v116M93 110h54" fill="none" stroke="#fff" stroke-opacity=".5" stroke-width="4"/>';
  if(item.category==='shoes') shape='<path d="m48 104 39-32 25 23 35 14 38 8q18 3 18 20v15H42v-25q0-16 6-23Z"/><path d="M42 139h161M103 98l-11 18m28-13-11 18m28-13-11 18" fill="none" stroke="#fff" stroke-opacity=".65" stroke-width="5"/>';
  if(item.category==='accessory') shape='<rect x="66" y="79" width="108" height="93" rx="15"/><path d="M91 80V61a29 29 0 0 1 58 0v19" fill="none" stroke="currentColor" stroke-width="10"/><rect x="107" y="106" width="26" height="18" rx="3" fill="#f2dfb2"/>';
  return `<svg class="clothing-art" viewBox="0 0 240 220" aria-hidden="true" style="color:${fill}"><ellipse cx="120" cy="199" rx="70" ry="7" fill="#24332b" opacity=".06"/><g fill="currentColor">${shape}</g></svg>`;
}
function itemPicture(item) { return item.photo?`<img src="${esc(item.photo)}" alt="${esc(item.name)}" loading="lazy">`:clothingArt(item); }
function itemCard(item) { return `<article class="item-card"><div class="item-image">${itemPicture(item)}<button type="button" class="icon-btn favorite-btn${item.favorite?' is-active':''}" data-action="favorite-item" data-id="${esc(item.id)}" aria-label="${item.favorite?'Убрать из избранного':'В избранное'}: ${esc(item.name)}" aria-pressed="${item.favorite}">${icon('heart')}</button>${!item.available?'<span class="availability-badge">В стирке</span>':''}</div><div class="card-body"><p class="eyebrow">${esc(CATEGORIES[item.category])}</p><h3>${esc(item.name)}</h3><div class="tag-row">${item.colors.map(color=>`<span class="color-dot" title="${esc(COLORS[color][0])}" style="background:${COLORS[color][1]}"><span class="sr-only">${esc(COLORS[color][0])}</span></span>`).join('')}<span class="item-meta">${esc(item.seasons.map(season=>SEASONS[season]).join(' · '))}</span></div>${item.size||item.style?`<p class="item-meta">${esc([item.size?`Размер ${item.size}`:'',item.style].filter(Boolean).join(' · '))}</p>`:''}<div class="card-actions"><button class="btn btn-ghost" data-action="edit-item" data-id="${esc(item.id)}" type="button">${icon('edit')}Изменить</button><button class="icon-btn" data-action="toggle-available" data-id="${esc(item.id)}" type="button" aria-label="${item.available?'Отправить в стирку':'Вернуть из стирки'}: ${esc(item.name)}" title="${item.available?'Отправить в стирку':'Вернуть из стирки'}">${icon(item.available?'sun':'check')}</button></div></div></article>`; }
function outfitCard(outfit) {
 const status=outfitStatus(outfit,state.items);const missing=outfit.missingItems||[];
 return `<article class="outfit-card"><div class="outfit-preview">${status.items.slice(0,4).map(item=>`<div class="outfit-piece">${itemPicture(item)}</div>`).join('')}${missing.map(missingPiece).join('')}${!status.items.length&&!missing.length?`<div class="empty-preview">${icon('outfits')}</div>`:''}<button class="icon-btn favorite-btn${outfit.favorite?' is-active':''}" type="button" data-action="favorite-outfit" data-id="${esc(outfit.id)}" aria-label="${outfit.favorite?'Убрать из избранного':'В избранное'}: ${esc(outfit.name)}" aria-pressed="${outfit.favorite}">${icon('heart')}</button></div><div class="card-body"><p class="eyebrow">${esc(plural(status.items.length,'ваша вещь','ваши вещи','ваших вещей'))}</p><h3>${esc(outfit.name)}</h3><p class="outfit-completeness${missing.length?' missing-outfit-badge':''}">${missing.length?'Требует покупки':status.missing.length?'Проверьте состав':'Полный'}</p><div class="tag-row"><span class="tag">${esc(OCCASIONS[outfit.occasion]||OCCASIONS.everyday)}</span>${outfit.style?`<span class="tag">${esc(STYLE_OPTIONS[outfit.style]||outfit.style)}</span>`:''}${outfit.season?`<span class="tag">${esc(SEASONS[outfit.season])}</span>`:''}</div>${outfit.description?`<p class="item-meta outfit-description">${esc(outfit.description)}</p>`:''}${status.missing.length?`<p class="outfit-warning">${esc(plural(status.missing.length,'вещь удалена','вещи удалены','вещей удалены'))}. Обновите состав.</p>`:''}${status.unavailable.length?'<p class="outfit-warning">Есть вещи в стирке</p>':''}${!status.missing.length&&!status.unavailable.length&&!missing.length?'<p class="item-meta">Всё готово к выходу</p>':''}${missing.length?`<details class="saved-missing-details"><summary>Недостающие детали · ${missing.length}</summary>${missing.map(item=>`<div class="saved-missing-item"><strong>${esc(item.name)}</strong><p>${esc(item.reason)}</p><button type="button" class="btn btn-secondary" data-action="shop-missing-outfit" data-id="${esc(outfit.id)}" data-missing-id="${esc(item.id)}">${icon('shopping')}В покупки</button>${storeLinks(item)}</div>`).join('')}</details>`:''}<div class="card-actions">${button('edit-outfit','Изменить','btn btn-ghost',outfit.id,'edit')}${button('plan-outfit','В календарь','btn btn-ghost',outfit.id,'calendar')}</div></div></article>`;
}
function empty(title,text,action,label,glyph='wardrobe') { return `<div class="empty-state"><div class="empty-icon">${icon(glyph)}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action?button(action,label,'btn btn-primary','','plus'):''}</div>`; }
function header(title,subtitle,action='',label='',glyph='plus') { return `<div class="page-header"><div><p class="eyebrow">ВАШ ЛИЧНЫЙ СТИЛЬ</p><h1>${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div>${action?button(action,label,'btn btn-primary','',glyph):''}</div>`; }
function homeView() {
 const favorites=state.items.filter(item=>item.favorite).length+state.outfits.filter(outfit=>outfit.favorite).length;
 const upcoming=state.plans.filter(plan=>plan.date>=localDate()).sort((a,b)=>a.date.localeCompare(b.date)||a.slot.localeCompare(b.slot))[0];
 const today=new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});
 return `<div class="dashboard-intro"><div><p class="eyebrow">ВАШЕ ПРОСТРАНСТВО СТИЛЯ</p><h2>${state.profile.name?`Здравствуйте, ${esc(state.profile.name)}`:'Добро пожаловать в MyCloset'}</h2></div><span class="today-date">${icon('calendar')}${esc(today)}</span></div>
 <section class="hero"><div class="hero-content"><p class="eyebrow">ГАРДЕРОБ, КОТОРЫЙ ВДОХНОВЛЯЕТ</p><h1>Ваш стиль<br><em>начинается здесь.</em></h1><p>Любимые вещи — в одном месте.<br>Собирайте образы и планируйте, что надеть.</p><div class="hero-actions">${button('suggest','Подобрать образ','btn btn-primary','','sparkle')}${button('new-outfit','Собрать вручную','btn btn-secondary','','plus')}</div></div><div class="hero-art"><img class="hero-photo" src="assets/style-editorial.webp" alt="Вдохновение: белая рубашка, джинсы и аксессуары в спокойных оттенках" fetchpriority="high"><div class="hero-photo-label">${icon('sparkle')}<div><strong>Простота. Детали. Вы.</strong><span>Идея для вдохновения</span></div></div></div></section>
 <div class="stats-grid"><button class="stat-card" data-nav="wardrobe" type="button"><span class="stat-icon">${icon('wardrobe')}</span><strong>${state.items.length}</strong><span>Вещей в гардеробе</span></button><button class="stat-card" data-nav="outfits" type="button"><span class="stat-icon">${icon('outfits')}</span><strong>${state.outfits.length}</strong><span>Сохранённых образов</span></button><button class="stat-card" data-nav="favorites" type="button"><span class="stat-icon">${icon('heart')}</span><strong>${favorites}</strong><span>В избранном</span></button><button class="stat-card" data-nav="calendar" type="button"><span class="stat-icon">${icon('calendar')}</span><strong>${state.plans.filter(plan=>plan.date>=localDate()).length}</strong><span>Предстоящих планов</span></button></div>
 ${weatherHost()}
 ${state.items.length?`<section class="recent-section"><div class="section-header"><div><p class="eyebrow">ВАША КОЛЛЕКЦИЯ</p><h2>Недавно в гардеробе</h2></div><button class="btn btn-ghost" data-nav="wardrobe" type="button">Все вещи ${icon('arrow-right')}</button></div><div class="card-grid">${state.items.slice(-4).reverse().map(itemCard).join('')}</div></section>`:`<section class="onboarding-panel"><div class="onboarding-head"><div><p class="eyebrow">НАЧНЁМ С ПРОСТОГО</p><h2>Ваш гардероб — с чистого листа</h2></div><p>Три шага к любимым сочетаниям</p></div><div class="onboarding-steps"><button class="onboarding-step" data-action="add-item" type="button"><span class="step-number">01</span><div class="step-copy"><h3>Добавьте любимую вещь</h3><p>Фото, цвет и сезон — всё, что нужно для начала.</p></div>${icon('arrow-right')}</button><button class="onboarding-step" data-action="new-outfit" type="button"><span class="step-number">02</span><div class="step-copy"><h3>Соберите первый образ</h3><p>Сочетайте вещи и сохраняйте удачные идеи.</p></div>${icon('arrow-right')}</button><button class="onboarding-step" data-nav="calendar" type="button"><span class="step-number">03</span><div class="step-copy"><h3>Освободите своё утро</h3><p>Выберите образ на день заранее в календаре.</p></div>${icon('arrow-right')}</button></div><div class="demo-note"><span>Хотите сначала познакомиться с возможностями?</span>${button('demo','Посмотреть на примере','btn btn-ghost','','arrow-right')}</div></section>`}
 <div class="split-panels"><section class="settings-card quick-panel"><div class="quick-panel-icon">${icon('calendar')}</div><div class="quick-panel-copy"><p class="eyebrow">ВАШ СЛЕДУЮЩИЙ ВЫХОД</p><h2>${upcoming?esc(dateLabel(upcoming.date)):'Утро без спешки'}</h2><p>${upcoming?`${esc(SLOTS[upcoming.slot])}: ${esc(state.outfits.find(outfit=>outfit.id===upcoming.outfitId)?.name || 'Образ')}`:'Продумайте образ заранее и оставьте больше времени для себя.'}</p><button class="btn btn-ghost" data-nav="calendar" type="button">Открыть календарь ${icon('arrow-right')}</button></div></section><section class="settings-card quick-panel style-tip"><div class="quick-panel-icon">${icon('sparkle')}</div><div class="quick-panel-copy"><p class="eyebrow">МАЛЕНЬКАЯ ИДЕЯ</p><h2>Начните с любимого</h2><p>Выберите одну любимую вещь и соберите вокруг неё новый образ. Иногда вдохновение уже в вашем шкафу.</p><button class="btn btn-ghost" data-nav="wardrobe" type="button">Заглянуть в гардероб ${icon('arrow-right')}</button></div></section></div>`;
}
function wardrobeView() { const results=filterItems(state.items,filters); return `${header('Мой гардероб','Каждая вещь на своём месте. Каждый образ — под рукой.')}<div class="filters"><label class="search-field">${icon('search')}<input class="search-input" id="wardrobe-search" data-filter="query" type="search" placeholder="Найти вещь, цвет или стиль" aria-label="Поиск вещей" value="${esc(filters.query)}"></label><select data-filter="category" aria-label="Категория"><option value="">Все категории</option>${Object.entries(CATEGORIES).map(([key,label])=>`<option value="${key}"${filters.category===key?' selected':''}>${label}</option>`).join('')}</select><select data-filter="color" aria-label="Цвет"><option value="">Все цвета</option>${Object.entries(COLORS).map(([key,[label]])=>`<option value="${key}"${filters.color===key?' selected':''}>${label}</option>`).join('')}</select><select data-filter="season" aria-label="Сезон"><option value="">Все сезоны</option>${Object.entries(SEASONS).map(([key,label])=>`<option value="${key}"${filters.season===key?' selected':''}>${label}</option>`).join('')}</select><select data-filter="availability" aria-label="Доступность"><option value="">Все вещи</option><option value="available"${filters.availability==='available'?' selected':''}>Готовы к выходу</option><option value="laundry"${filters.availability==='laundry'?' selected':''}>В стирке</option></select></div><div class="results-line"><span>${esc(plural(results.length,'вещь','вещи','вещей'))}</span>${Object.values(filters).some(Boolean)?button('reset-filters','Сбросить фильтры','btn btn-ghost'):''}</div>${results.length?`<div class="card-grid">${results.map(itemCard).join('')}</div>`:state.items.length?empty('Ничего не нашлось','Попробуйте другой запрос или сбросьте фильтры.','reset-filters','Сбросить фильтры','search'):empty('Ваш гардероб начинается здесь','Добавьте любимую футболку, удобные джинсы или пару обуви.','add-item','Добавить вещь')}`; }
function outfitsView() { return `${header('Мои образы','Сочетания, к которым хочется возвращаться.','new-outfit','Собрать образ')}<div class="section-header"><p class="subtitle">${esc(plural(state.outfits.length,'сохранённый образ','сохранённых образа','сохранённых образов'))}</p><div class="outfits-tools"><button class="btn btn-ghost" data-nav="favorites" type="button">${icon('heart')}Избранное</button>${button('suggest','Подобрать образ','btn btn-secondary','','sparkle')}</div></div>${state.outfits.length?`<div class="card-grid outfit-grid">${state.outfits.slice().reverse().map(outfitCard).join('')}</div>`:empty('Что наденем сегодня?','Выберите вещи из гардероба, дайте образу название и сохраните его.','new-outfit','Собрать первый образ','outfits')}<p class="footnote">Стилист учитывает повод, стиль, цвета и погоду. Каждый предложенный образ можно изменить и сохранить.</p>`; }
function favoritesView() { const items=state.items.filter(item=>item.favorite); const outfits=state.outfits.filter(outfit=>outfit.favorite); return `${header('Избранное','Вещи и сочетания, которые особенно вам нравятся.')}${!items.length&&!outfits.length?empty('Сохраните то, что любите','Нажмите на сердечко у вещи или образа — они появятся здесь.','','','heart'):''}${items.length?`<section><div class="section-header"><h2>Любимые вещи</h2><span class="tag">${items.length}</span></div><div class="card-grid">${items.map(itemCard).join('')}</div></section>`:''}${outfits.length?`<section><div class="section-header"><h2>Любимые образы</h2><span class="tag">${outfits.length}</span></div><div class="card-grid outfit-grid">${outfits.map(outfitCard).join('')}</div></section>`:''}`; }
function calendarView() { const monthName=displayedMonth.toLocaleDateString('ru-RU',{month:'long',year:'numeric'}); const plans=state.plans.filter(plan=>plan.date===selectedDate); return `${header('Календарь образов','Продумайте день заранее — оставьте утро для себя.','add-plan','Запланировать образ','calendar')}<div class="calendar-layout"><section class="calendar-panel"><div class="calendar-toolbar"><button class="icon-btn" data-action="prev-month" aria-label="Предыдущий месяц">${icon('chevron-left')}</button><h2>${esc(monthName)}</h2><button class="icon-btn" data-action="next-month" aria-label="Следующий месяц">${icon('chevron-right')}</button><button class="btn btn-ghost" data-action="today">Сегодня</button></div><div class="calendar-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(day=>`<span class="calendar-weekday">${day}</span>`).join('')}${monthCells(displayedMonth.getFullYear(),displayedMonth.getMonth()).map(date=>date?`<button class="calendar-cell${date===selectedDate?' is-active':''}${date===localDate()?' is-today':''}" data-action="select-date" data-date="${date}" aria-label="${esc(dateLabel(date))}${state.plans.some(plan=>plan.date===date)?', есть планы':''}" aria-pressed="${date===selectedDate}"><span class="calendar-day">${Number(date.slice(-2))}</span><span class="calendar-slots">${state.plans.filter(plan=>plan.date===date).map(plan=>`<span class="calendar-plan-dot" title="${esc(SLOTS[plan.slot])}"></span>`).join('')}</span></button>`:'<div class="calendar-cell calendar-empty" aria-hidden="true"></div>').join('')}</div></section><aside class="settings-card calendar-details"><p class="eyebrow">ВЫБРАННЫЙ ДЕНЬ</p><h2>${esc(dateLabel(selectedDate))}</h2>${button('stylist-date','Подобрать на эту дату','btn btn-secondary','','sparkle')}${Object.entries(SLOTS).map(([slot,label])=>{const plan=plans.find(plan=>plan.slot===slot);const outfit=state.outfits.find(outfit=>outfit.id===plan?.outfitId);return `<div class="calendar-entry"><p class="eyebrow">${label}</p>${outfit?`<h3>${esc(outfit.name)}</h3>${!outfitStatus(outfit,state.items).complete?`<p class="outfit-warning">${outfit.missingItems?.length?'Для этого образа ещё нужны покупки.':'Проверьте состав: есть недоступные вещи.'}</p>`:''}<div class="card-actions">${button('edit-plan','Изменить','btn btn-ghost',plan.id,'edit')}${button('delete-plan','Убрать','btn btn-ghost',plan.id,'trash')}</div>`:`<p class="item-meta">Пока без планов</p><button class="btn btn-ghost" data-action="add-plan" data-slot="${slot}">${icon('plus')}Выбрать образ</button>`}</div>`;}).join('')}</aside></div>`; }
function colorCheckboxes(selected=[],prefix='color') { return Object.entries(COLORS).map(([key,[label,fill]])=>`<label class="color-choice"><input type="checkbox" name="${prefix}" value="${key}"${selected.includes(key)?' checked':''}><span class="swatch" style="background:${fill}"></span><span>${label}</span></label>`).join(''); }
function settingsView() { return `${header('Настройки','Сделайте MyCloset немного ближе к себе.')}<div class="settings-layout"><form id="profile-form" class="settings-card"><p class="eyebrow">ЛИЧНЫЙ ПРОФИЛЬ</p><h2>Как к вам обращаться?</h2><div class="form-grid"><label class="field">Имя<input name="name" maxlength="80" autocomplete="given-name" placeholder="Ваше имя" value="${esc(state.profile.name)}"></label><label class="field">Город <span class="optional">необязательно</span><input name="city" maxlength="120" autocomplete="address-level2" placeholder="Например, Кызылорда" value="${esc(state.profile.city)}"></label><label class="field full-width">Любимые стили <span class="optional">необязательно</span><input name="styles" maxlength="200" placeholder="Минимализм, повседневный, классика…" value="${esc(state.profile.styles)}"></label></div><fieldset class="field"><legend>Любимые цвета</legend><div class="color-choices">${colorCheckboxes(state.profile.colors,'colors')}</div></fieldset><p class="footnote">Для точной погоды выберите город из поиска. Предпочтения профиля сохраняются для вас; стиль образа задаётся в стилисте.</p>${button('choose-city',state.profile.location?'Город для погоды: '+state.profile.location.name:'Выбрать город для погоды','btn btn-secondary','','pin')}<div class="form-actions"><button class="btn btn-primary" type="submit">Сохранить профиль</button></div></form><div class="settings-side"><section class="settings-card"><p class="eyebrow">ВАШИ ДАННЫЕ</p><h2>Всегда под рукой</h2><p>Это первая локальная версия: данные хранятся в этом браузере на этом устройстве. Аккаунта и синхронизации пока нет. Очистка данных браузера удалит гардероб.</p><p class="storage-status">${storageMode==='persistent'?'✓ Локальное сохранение работает.':esc(storageIssue)}</p><div class="backup-actions">${button('export','Скачать резервную копию','btn btn-secondary','','download')}${button('import','Загрузить копию','btn btn-secondary','','upload')}</div><p class="footnote">Копия содержит профиль, фотографии, вещи, образы, покупки и планы. Сохраняйте её время от времени.</p></section><section class="settings-card"><p class="eyebrow">ЧИСТЫЙ ЛИСТ</p><h2>Начать заново</h2><p>Удалить гардероб, образы, покупки, календарь и профиль из этого браузера.</p>${button('reset','Удалить все данные','btn btn-danger','','trash')}</section></div></div>`; }
function render() { const focused=document.activeElement?.id==='wardrobe-search'; const position=focused?document.activeElement.selectionStart:null; main.innerHTML=storageWarning()+({home:homeView,wardrobe:wardrobeView,stylist:stylistView,outfits:outfitsView,shopping:shoppingView,favorites:favoritesView,calendar:calendarView,settings:settingsView}[page])(); document.querySelectorAll('[data-nav]').forEach(node=>{const active=node.dataset.nav===page;node.classList.toggle('is-active',active);if(active)node.setAttribute('aria-current','page');else node.removeAttribute('aria-current');}); const moreButton=document.querySelector('.mobile-nav [data-action="open-more"]');const moreActive=['shopping','favorites','settings'].includes(page);if(moreButton){moreButton.classList.toggle('is-active',moreActive);if(moreActive)moreButton.setAttribute('aria-current','page');else moreButton.removeAttribute('aria-current');} document.title=`${labels[page]} — MyCloset`; document.querySelector('#current-page').textContent=labels[page]; if(focused){const input=document.querySelector('#wardrobe-search');input?.focus();try{input?.setSelectionRange(position,position);}catch{}} hydrateWeather(); }
function selectOptions(options, selected) { return Object.entries(options).map(([key,label])=>`<option value="${esc(key)}"${key===selected?' selected':''}>${esc(label)}</option>`).join(''); }
const money = value => `${new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(value)} ₸`;
function missingPiece(item) { return `<div class="missing-piece"><span class="missing-piece-icon">${icon('shopping')}</span><span class="missing-piece-label">Нужно добавить</span><strong>${esc(item.name)}</strong></div>`; }
function storeLinks(item) { const links=createStoreSearchLinks(item);return links.length?`<details class="shopping-store-links"><summary>Поиск похожих</summary><p class="footnote">Откроется поиск в магазине. Наличие, цены и подходящий размер проверяйте на его сайте.</p><div>${links.map(link=>`<a class="shopping-link" href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">${esc(link.name)} ${icon('arrow-right')}</a>`).join('')}</div></details>`:''; }
function shoppingCard(item) {
 const owned=state.items.some(garment=>garment.id===item.itemId);
 return `<article class="shopping-card" data-shopping-id="${esc(item.id)}"><div class="shopping-card-header"><div class="shopping-illustration" aria-hidden="true">${clothingArt(item)}</div><span class="shopping-status${item.status==='purchased'?' is-purchased':''}">${item.status==='purchased'?'Куплено':'В планах'}</span></div><div class="shopping-card-body"><p class="eyebrow">${esc(CATEGORIES[item.category])}</p><h3>${esc(item.name)}</h3><div class="shopping-meta tag-row">${item.colors.map(color=>`<span class="color-dot" title="${esc(COLORS[color][0])}" style="background:${COLORS[color][1]}"><span class="sr-only">${esc(COLORS[color][0])}</span></span>`).join('')}${[item.season?SEASONS[item.season]:'',item.size?`Размер ${item.size}`:'',item.style?STYLE_OPTIONS[item.style]||item.style:''].filter(Boolean).map(label=>`<span class="tag">${esc(label)}</span>`).join('')}</div><p class="shopping-budget">${item.budget!==null?`Ваш бюджет: до <strong>${esc(money(item.budget))}</strong>`:'Бюджет не указан'}</p>${item.notes?`<p class="shopping-notes">${esc(item.notes)}</p>`:''}${storeLinks(item)}<div class="shopping-actions">${button('edit-shopping','Изменить','btn btn-ghost',item.id,'edit')}${button(item.status==='purchased'?'reopen-shopping':'purchase-shopping',item.status==='purchased'?'Снова в план':'Отметить купленным','btn btn-secondary',item.id,item.status==='purchased'?'refresh':'check')}${item.status==='purchased'?owned?'<span class="shopping-added">✓ Уже в гардеробе</span>':button('shopping-to-wardrobe','Добавить в гардероб','btn btn-primary',item.id,'plus'):''}${button('delete-shopping','Удалить','btn btn-ghost',item.id,'trash')}</div></div></article>`;
}
function shoppingView() {
 const list=state.shoppingList.filter(item=>shoppingFilter==='all'||item.status===shoppingFilter);
 const planned=state.shoppingList.filter(item=>item.status==='planned');const budgeted=planned.filter(item=>item.budget!==null);const total=budgeted.reduce((sum,item)=>sum+item.budget,0);
 return `${header('Хочу в свой гардероб','Продуманные покупки для ваших любимых образов.','new-shopping','Добавить желание','plus')}<div class="shopping-toolbar"><div class="shopping-tabs" role="group" aria-label="Показать покупки">${[['planned','В планах'],['purchased','Куплено'],['all','Все']].map(([key,label])=>`<button type="button" class="${key===shoppingFilter?'is-active':''}" data-action="shopping-filter" data-id="${key}" aria-pressed="${key===shoppingFilter}">${esc(label)}<span>${state.shoppingList.filter(item=>key==='all'||item.status===key).length}</span></button>`).join('')}</div>${budgeted.length?`<p class="shopping-total">Запланированный бюджет: <strong>${esc(money(total))}</strong><span>Сумма ваших лимитов · ${budgeted.length} из ${planned.length} покупок</span></p>`:''}</div><p class="footnote shopping-intro">Здесь ваши желания и бюджет, который вы указали сами. Ссылки ведут на поиск в магазинах; реальные товары и цены сайт не загружает.</p>${list.length?`<div class="shopping-grid">${list.slice().reverse().map(shoppingCard).join('')}</div>`:empty(shoppingFilter==='purchased'?'Пока без покупок':shoppingFilter==='all'?'Оставьте место для желаний':'Всё нужное — по плану',shoppingFilter==='purchased'?'Когда найдёте подходящую вещь, отметьте её купленной.':'Добавьте вещь вручную или сохраните недостающую деталь из образа.','new-shopping','Добавить желание','shopping')}`;
}
function shoppingDuplicate(saved,excludeId='') { const normalized=value=>String(value).trim().toLocaleLowerCase('ru').replace(/\s+/g,' ');return state.shoppingList.find(item=>item.id!==excludeId&&item.status==='planned'&&saved.status==='planned'&&item.category===saved.category&&normalized(item.name)===normalized(saved.name)&&normalized(item.size)===normalized(saved.size)&&[...item.colors].sort().join(',')===[...saved.colors].sort().join(',')); }
function shoppingDialog(id='',prefill=null,onReturn=null) {
 dialogReturn=onReturn;
 const existing=state.shoppingList.find(item=>item.id===id);
 const draft=existing||{id:uid(),name:'',category:'top',colors:[],season:'',style:'',size:'',budget:null,notes:'',status:'planned',itemId:'',createdAt:new Date().toISOString(),...prefill};
 const body=`<div class="form-grid"><label class="field full-width">Название *<input name="name" required maxlength="100" autofocus placeholder="Например, бежевый тренч" value="${esc(draft.name)}"></label><label class="field">Категория<select name="category">${selectOptions(CATEGORIES,draft.category)}</select></label><label class="field">Сезон<select name="season"><option value="">Любой сезон</option>${selectOptions(SEASONS,draft.season)}</select></label><label class="field">Размер<input name="size" maxlength="30" placeholder="M, 38…" value="${esc(draft.size)}"></label><label class="field">Стиль<input name="style" maxlength="100" placeholder="Повседневный, классика…" value="${esc(draft.style)}"></label><label class="field">Ваш бюджет, ₸<input name="budget" type="number" min="0" max="100000000" step="any" placeholder="Необязательно" value="${draft.budget===null?'':esc(draft.budget)}"></label><label class="field">Статус<select name="status"><option value="planned"${draft.status==='planned'?' selected':''}>В планах</option><option value="purchased"${draft.status==='purchased'?' selected':''}>Куплено</option></select></label></div><p class="footnote">Бюджет — ваш личный лимит, не цена товара.</p><fieldset class="field"><legend>Желаемые цвета <span class="optional">необязательно</span></legend><div class="color-choices">${colorCheckboxes(draft.colors)}</div></fieldset><label class="field">Заметка<textarea name="notes" maxlength="500" rows="3" placeholder="Материал, посадка или к какому образу нужна вещь">${esc(draft.notes)}</textarea></label>`;
 openDialog(dialog(existing?'Изменить желание':'Новое желание','Сохраните детали, чтобы выбрать подходящую вещь.',body,'Сохранить желание','shopping-form'));
 modal.querySelector('form').addEventListener('submit',event=>{event.preventDefault();runSubmission(event.currentTarget,async()=>{
  const form=new FormData(event.currentTarget);const name=String(form.get('name')).trim();if(!name)throw new Error('Введите название вещи.');const rawBudget=String(form.get('budget')).trim();const budget=rawBudget===''?null:Number(rawBudget);if(budget!==null&&(!Number.isFinite(budget)||budget<0||budget>100000000))throw new Error('Укажите бюджет от 0 до 100 000 000 ₸ или оставьте поле пустым.');
  const saved={...draft,id:existing?.id||draft.id||uid(),name,category:form.get('category'),colors:form.getAll('color'),season:form.get('season'),style:String(form.get('style')).trim(),size:String(form.get('size')).trim(),budget,notes:String(form.get('notes')).trim(),status:form.get('status')};
  if(saved.status==='planned')saved.itemId='';
  const duplicate=shoppingDuplicate(saved,saved.id);
  if(duplicate)throw new Error('Такая вещь уже есть в планах покупок. Откройте её в списке, чтобы изменить детали.');
  const next=cloneState();if(existing)next.shoppingList=next.shoppingList.map(item=>item.id===existing.id?saved:item);else next.shoppingList.push(saved);await commit(next,existing?'Желание обновлено':'Добавлено в покупки');closeDialog();
 });});
}
function moreDialog() { openDialog(`<div class="more-menu"><div class="modal-header"><div><p class="eyebrow">MYCLOSET</p><h2 id="modal-title">Ещё для вашего стиля</h2></div><button class="icon-btn" type="button" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${[['shopping','shopping','Покупки','Желания и продуманный бюджет'],['favorites','heart','Избранное','Любимые вещи и образы'],['settings','settings','Настройки','Профиль и резервные копии']].map(([nav,glyph,title,subtitle])=>`<button class="more-menu-link" type="button" data-nav="${nav}">${icon(glyph)}<span><strong>${title}</strong><small>${subtitle}</small></span>${icon('arrow-right')}</button>`).join('')}</div></div>`); }
function weatherKey(location=state.profile.location) { return location?`${location.latitude},${location.longitude}`:''; }
async function apiJson(url) {
 const response=await fetch(url,{headers:{Accept:'application/json'}});
 let data;try{data=await response.json();}catch{throw new Error('Сервер вернул непонятный ответ. Попробуйте ещё раз.');}
 if(!response.ok)throw new Error(data.error || 'Не удалось загрузить данные.');
 return data;
}
function cachedWeather() { const cached=weatherCache.get(weatherKey());return cached&&Date.now()-cached.at<10*60*1000?cached.data:null; }
async function loadWeather(refresh=false) {
 const location=state.profile.location;const key=weatherKey(location);if(!key)return null;
 if(weatherPending.has(key))return weatherPending.get(key);
 if(!refresh&&cachedWeather())return cachedWeather();
 const promise=apiJson(`/api/weather?lat=${encodeURIComponent(location.latitude)}&lon=${encodeURIComponent(location.longitude)}${refresh?'&refresh=1':''}`).then(data=>{weatherCache.set(key,{data,at:Date.now()});return data;}).finally(()=>weatherPending.delete(key));
 weatherPending.set(key,promise);return promise;
}
const degrees=value=>Number.isFinite(value)?`${Math.round(value)}°`:'—';
function weatherDescription(code) {
 if(code===null||code===undefined)return 'Погода';
 if(code===0)return 'Ясно';if(code<=3)return 'Облачно';if(code<=48)return 'Туман';if(code<=67)return 'Дождь';if(code<=77)return 'Снег';if(code<=82)return 'Ливень';if(code<=86)return 'Снегопад';return 'Гроза';
}
function weatherGlyph(code) { return code===0?'sun':code!==null&&code>=51?'rain':'cloud'; }
function weatherMarkup(date,data=null,error='',loading=false) {
 const location=state.profile.location;
 if(!location)return `<div class="weather-placeholder"><span class="weather-symbol">${icon('cloud')}</span><div><p class="eyebrow">ПОГОДА И ВАШ ГАРДЕРОБ</p><h2>У каждого дня свой образ</h2><p>Выберите город, чтобы учитывать температуру, дождь и ветер при подборе.</p>${button('choose-city','Выбрать город','btn btn-secondary','','pin')}</div></div>`;
 const day=data?.days?.find(value=>value.date===date);
 const current=data?.current?.dateTime?.slice(0,10)===date?data.current:null;
 const headline=current?degrees(current.temperature):day?`${degrees(day.tempMin)} / ${degrees(day.tempMax)}`:'—';
 const rain=day?.rainProbability;const wind=current?.windSpeed??day?.windSpeed;const code=current?.weatherCode??day?.weatherCode;
 const updated=data?.updatedAt?new Date(data.updatedAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'';
 return `<div class="weather-card-header"><div><p class="eyebrow">${esc(dateLabel(date))}</p><h2 class="weather-location">${icon('pin')}${esc(location.name)}</h2></div>${button('choose-city','Сменить город','btn btn-ghost')}</div>${error?`<p class="weather-error" role="alert">${esc(error)} В стилисте можно указать погоду вручную.</p>`:''}${loading?'<p class="weather-status" role="status">Загружаем прогноз…</p>':''}${data&&!day&&!current?'<p class="weather-status">На выбранную дату прогноза пока нет. Укажите погоду вручную или выберите другую дату.</p>':''}<div class="weather-current"><span class="weather-symbol">${icon(weatherGlyph(code))}</span><strong class="weather-temperature">${headline}</strong><div><span>${day||current?esc(weatherDescription(code)):'Прогноз ещё не загружен'}</span>${current?`<p class="item-meta">Сейчас · ощущается как ${degrees(current.feelsLike)}</p>`:day?`<p class="item-meta">Ощущается ${degrees(day.feelsMin)} / ${degrees(day.feelsMax)}</p>`:''}</div></div>${day||current?`<div class="weather-facts"><span>${icon('rain')}Вероятность осадков: ${Number.isFinite(rain)?`${rain}%`:'нет данных'}</span><span>${icon('wind')}Ветер: ${Number.isFinite(wind)?`${Math.round(wind*10)/10} м/с`:'нет данных'}</span></div>`:''}<div class="weather-meta">${data?`<span>Источник: <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a>${updated?` · обновлено ${esc(updated)}`:''}</span>`:'<span>Прогноз появится при подключении к интернету.</span>'}${button('refresh-weather','Обновить','btn btn-ghost','','refresh')}</div>`;
}
function weatherHost(date=localDate()) { return `<section class="settings-card weather-card" data-weather-host data-date="${esc(date)}" aria-label="Прогноз погоды">${weatherMarkup(date,cachedWeather())}</section>`; }
async function hydrateWeather(refresh=false) {
 const hosts=[...main.querySelectorAll('[data-weather-host]')];if(!hosts.length||!state.profile.location)return;
 const key=weatherKey();hosts.forEach(host=>host.innerHTML=weatherMarkup(host.dataset.date,cachedWeather(),'',true));
 try{const data=await loadWeather(refresh);if(key!==weatherKey())return;for(const host of hosts)if(host.isConnected)host.innerHTML=weatherMarkup(host.dataset.date,data);}
 catch(error){if(key!==weatherKey())return;for(const host of hosts)if(host.isConnected)host.innerHTML=weatherMarkup(host.dataset.date,cachedWeather(),error.message);}
}
function cityDialog() {
 let results=[];let request=0;
 openDialog(dialog('Выберите город','Найдите свой город и проверьте регион в результатах поиска.',`<div class="city-picker"><label class="field">Город<input id="city-query" name="query" type="search" minlength="2" maxlength="80" required autofocus placeholder="Например, Кызылорда" value="${esc(state.profile.city)}"></label><p class="footnote">Геолокация не нужна. Для поиска города и погоды используется Open-Meteo.</p><div id="city-results" class="city-results" aria-live="polite"></div></div>`,'Найти город','city-form'));
 const form=modal.querySelector('form');const resultNode=modal.querySelector('#city-results');const queryInput=modal.querySelector('#city-query');
 queryInput.addEventListener('input',()=>{request++;results=[];resultNode.innerHTML='';});
 form.addEventListener('submit',async event=>{event.preventDefault();const query=queryInput.value.trim();if(query.length<2){formError(new Error('Введите хотя бы две буквы.'));return;}const token=++request;const submit=form.querySelector('[type="submit"]');submit.disabled=true;resultNode.innerHTML='<p class="weather-status" role="status">Ищем город…</p>';const errorNode=modal.querySelector('#form-error');if(errorNode)errorNode.hidden=true;
 try{const data=await apiJson(`/api/cities?q=${encodeURIComponent(query)}`);if(!form.isConnected||token!==request)return;results=data.cities;resultNode.innerHTML=results.length?results.map((city,index)=>`<button type="button" class="city-result" data-city-index="${index}"><span>${icon('pin')}<strong>${esc(city.name)}</strong></span><span class="city-result-meta">${esc([city.admin1,city.country].filter(Boolean).join(', '))}</span></button>`).join(''):'<p class="weather-status">Город не найден. Попробуйте другое написание.</p>';}catch(error){if(form.isConnected&&token===request){resultNode.innerHTML='';formError(error);}}finally{if(form.isConnected)submit.disabled=false;}
 });
 resultNode.addEventListener('click',event=>{const target=event.target.closest('[data-city-index]');if(!target)return;const city=results[Number(target.dataset.cityIndex)];if(!city)return;runSubmission(form,async()=>{const next=cloneState();next.profile={...next.profile,city:city.name,location:city};stylistResult=null;stylistRequest++;await commit(next,`Город выбран: ${city.name}`);closeDialog();});});
}
function manualWeatherFields() { return `<div class="manual-weather form-grid"><label class="field">Ощущаемая температура, °C *<input name="feelsLike" type="number" step="0.1" min="-60" max="60" value="${esc(stylistCriteria.feelsLike)}" placeholder="Например, 12"${stylistCriteria.weatherMode==='manual'?' required':''}></label><label class="field">Вероятность осадков, % *<input name="rainProbability" type="number" min="0" max="100" value="${esc(stylistCriteria.rainProbability)}" placeholder="0–100"${stylistCriteria.weatherMode==='manual'?' required':''}></label><label class="field">Ветер, м/с *<input name="windSpeed" type="number" step="0.1" min="0" max="60" value="${esc(stylistCriteria.windSpeed)}" placeholder="Например, 3"${stylistCriteria.weatherMode==='manual'?' required':''}></label><p class="footnote full-width">Указано вручную для ${esc(dateLabel(stylistCriteria.date))}. Эти значения не являются прогнозом.</p></div>`; }
function stylistWeatherPanel() { return stylistCriteria.weatherMode==='manual'?manualWeatherFields():stylistCriteria.weatherMode==='ignore'?'<p class="notice">Погода не учитывается. Подбор использует выбранный сезон, повод и сочетаемость вещей.</p>':weatherHost(stylistCriteria.date); }
function recommendationCard(outfit,index) {
 const items=outfit.itemIds.map(id=>state.items.find(item=>item.id===id)).filter(Boolean);const missing=outfit.missingItems||[];
 return `<article class="recommendation-card"><div class="recommendation-preview"><span class="recommendation-number">0${index+1}</span><div class="recommendation-pieces">${items.map(item=>`<div class="outfit-piece" title="${esc(item.name)}">${itemPicture(item)}</div>`).join('')}${missing.map(missingPiece).join('')}</div></div><div class="recommendation-body"><p class="eyebrow">${esc(OCCASIONS[stylistCriteria.occasion])}</p><h3>${esc(outfit.title)}</h3>${missing.length?'<p class="missing-outfit-badge">Требует покупки</p>':''}<p>${esc(outfit.description)}</p><div class="tag-row">${items.map(item=>`<span class="tag">${esc(item.name)}</span>`).join('')}</div>${outfit.warnings.length?'<p class="recommendation-caution">Проверьте рекомендации перед выходом</p>':''}<details class="recommendation-details"><summary>${outfit.warnings.length?'Почему этот образ · что проверить':'Почему этот образ?'}</summary>${outfit.reasons.length?`<ul class="recommendation-reasons">${outfit.reasons.map(reason=>`<li>${icon('check')}${esc(reason)}</li>`).join('')}</ul>`:''}${outfit.warnings.map(warning=>`<p class="recommendation-warning">${esc(warning)}</p>`).join('')}</details>${missing.length?`<details class="saved-missing-details"><summary>Что добавить · ${missing.length}</summary>${missing.map(item=>`<div class="saved-missing-item"><strong>${esc(item.name)}</strong><p>${esc(item.reason)}</p><button type="button" class="btn btn-secondary" data-action="shop-missing-recommendation" data-id="${index}" data-missing-id="${esc(item.id)}">${icon('shopping')}В покупки</button>${storeLinks(item)}</div>`).join('')}</details>`:''}${button('save-recommendation','Изменить и сохранить','btn btn-primary',String(index),'plus')}</div></article>`;
}
function stylistResultsView() {
 if(!stylistResult)return `<div class="stylist-waiting"><span class="empty-icon">${icon('sparkle')}</span><p class="eyebrow">ВАШЕ НОВОЕ СОЧЕТАНИЕ</p><h2>Вдохновение уже в гардеробе</h2><p>Выберите, куда собираетесь. Мы предложим до трёх сочетаний из ваших доступных вещей и объясним выбор.</p><div class="stylist-steps"><span>01 · Укажите повод</span><span>02 · Учтите погоду</span><span>03 · Сохраните образ</span></div></div>`;
 const hasPartial=stylistResult.outfits.some(outfit=>outfit.missingItems?.length);
 const missing=(stylistResult.missingCategories||[]).filter(key=>!state.items.some(item=>item.category===key)).map(key=>CATEGORIES[key]||key);
 const ownedBase=state.items.some(item=>item.category==='dress')||(state.items.some(item=>item.category==='top')&&state.items.some(item=>item.category==='bottom'));
 const warnings=[...new Set(stylistResult.warnings.filter(warning=>!hasPartial||!warning.startsWith('Полный комплект не собран.')).map(warning=>warning.startsWith('Для указанного холода')&&state.items.some(item=>item.category==='outerwear')?'Для холода нет подходящей верхней одежды. Проверьте характеристики своей вещи или измените условия подбора.':warning==='Для основы нужны верх и низ либо платье.'&&ownedBase?'Для выбранных условий не найдена подходящая основа. Проверьте доступность и сезон своих вещей.':warning))];
 const emptyResult=missing.length?empty('В гардеробе не хватает деталей','Добавьте свои вещи недостающих категорий или измените условия подбора.','add-item','Добавить вещь'):empty('Проверьте условия подбора','Вещи уже есть в гардеробе. Проверьте доступность, сезон и погоду или соберите образ вручную.','new-outfit','Собрать вручную','outfits');
 return `<div class="stylist-results-header"><div><p class="eyebrow">ПОДОБРАНО ДЛЯ ВАС</p><h2>${hasPartial?'Что дополнит ваш гардероб':stylistResult.outfits.length?'Готовые идеи на ваш день':'Пока не нашлось сочетания'}</h2><p>${esc(dateLabel(stylistCriteria.date))} · ${esc(OCCASIONS[stylistCriteria.occasion])}</p></div>${stylistResult.outfits.length?button('rerun-stylist','Ещё варианты','btn btn-secondary','','refresh'):''}</div>${warnings.map(warning=>`<p class="notice">${esc(warning)}</p>`).join('')}${!hasPartial&&missing.length?`<p class="notice">В вашем гардеробе пока нет: ${esc(missing.join(', '))}.</p>`:''}${stylistResult.outfits.length?`<div class="recommendation-grid">${stylistResult.outfits.map(recommendationCard).join('')}</div>`:emptyResult}`;
}
function stylistView() {
 const c=stylistCriteria;
 return `${header('Что наденем сегодня?','Ваш гардероб, новые сочетания и чуть больше времени для себя.')}<div class="stylist-intro"><span class="rule-badge">${icon('sparkle')}Подбор по правилам</span><p>Учитываем повод, стиль, цвета, сезон и погоду. Сначала предложим готовые сочетания. Если чего-то не хватает — покажем, что можно добавить.</p></div><div class="stylist-layout"><section class="settings-card stylist-controls"><p class="eyebrow">ВАШИ ПЛАНЫ</p><h2>Образ для вашего дня</h2><form id="stylist-form" class="stylist-form"><label class="field">Куда собираетесь?<select name="occasion">${selectOptions(OCCASIONS,c.occasion)}</select></label><div class="form-grid"><label class="field">Стиль<select name="style">${selectOptions(STYLE_OPTIONS,c.style)}</select></label><label class="field">Сезон<select name="season"><option value="">Любой сезон</option>${selectOptions(SEASONS,c.season)}</select></label></div><label class="field">На какую дату?<input type="date" name="date" required min="1900-01-01" max="2200-12-31" value="${esc(c.date)}"></label><label class="field">Начать с любимой вещи<select name="anchorItemId"><option value="">Довериться подбору</option>${state.items.filter(item=>item.available).map(item=>`<option value="${esc(item.id)}"${item.id===c.anchorItemId?' selected':''}>${esc(item.name)}</option>`).join('')}</select></label><fieldset class="field"><legend>Как учитывать погоду?</legend><div class="weather-mode-options">${[['auto','Прогноз'],['manual','Вручную'],['ignore','Без погоды']].map(([key,label])=>`<label class="weather-mode-option"><input type="radio" name="weatherMode" value="${key}"${key===c.weatherMode?' checked':''}><span>${label}</span></label>`).join('')}</div></fieldset><div id="stylist-weather-panel">${stylistWeatherPanel()}</div><p id="stylist-error" class="form-error" role="alert" hidden></p><button class="btn btn-primary stylist-submit" type="submit">${icon('sparkle')}Подобрать образ</button><p class="footnote">Подбор работает без внешнего ИИ. Теплоту и защиту от дождя можно уточнить в карточке каждой вещи.</p></form></section><section id="stylist-results" class="stylist-results" aria-live="polite">${stylistResultsView()}</section></div>`;
}
function readStylistCriteria(form) { const data=new FormData(form);for(const key of Object.keys(stylistCriteria))stylistCriteria[key]=String(data.get(key)??stylistCriteria[key]); }
function invalidateStylist() { stylistRequest++;stylistResult=null;const target=main.querySelector('#stylist-results');if(target)target.innerHTML=stylistResultsView(); }
function manualWeather() { const result={};for(const [key,min,max] of [['feelsLike',-60,60],['rainProbability',0,100],['windSpeed',0,60]]){if(stylistCriteria[key].trim()==='')throw new Error('Заполните все три значения погоды вручную.');const value=Number(stylistCriteria[key]);if(!Number.isFinite(value)||value<min||value>max)throw new Error('Проверьте введённую погоду: температура от −60 до 60 °C, осадки 0–100%, ветер 0–60 м/с.');result[key]=value;}return result; }
async function runStylist(rerun=false) {
 const form=main.querySelector('#stylist-form');if(!form||stylistBusy)return;if(!form.reportValidity())return;readStylistCriteria(form);const criteria={...stylistCriteria};const token=++stylistRequest;const locationKey=weatherKey();const errorNode=form.querySelector('#stylist-error');errorNode.hidden=true;const submit=form.querySelector('[type="submit"]');stylistBusy=true;submit.disabled=true;submit.textContent='Подбираем…';
 try{let weather=null;if(criteria.weatherMode==='manual')weather=manualWeather();if(criteria.weatherMode==='auto'){if(!state.profile.location)throw new Error('Выберите город, укажите погоду вручную или выберите «Без погоды».');const data=await loadWeather();const day=data.days.find(value=>value.date===criteria.date);if(!day)throw new Error('На выбранную дату нет прогноза. Укажите погоду вручную или выберите «Без погоды».');if(!Number.isFinite(day.feelsMin)||!Number.isFinite(day.feelsMax))throw new Error('В прогнозе нет ощущаемой температуры. Укажите погоду вручную.');weather={...day,feelsLike:day.feelsMin};}
 if(!form.isConnected||token!==stylistRequest||locationKey!==weatherKey())return;
 stylistVariant=rerun?stylistVariant+1:0;const options={...criteria,weather,limit:3,variant:stylistVariant};const full=recommendOutfits(state.items,options);const partial=full.outfits.length?null:buildMissingRecommendations(state.items,options,full);stylistResult=partial?{...full,outfits:partial.outfits,warnings:[...new Set([...full.warnings,...partial.warnings])]}:full;const target=main.querySelector('#stylist-results');if(target)target.innerHTML=stylistResultsView();
 }catch(error){if(form.isConnected&&token===stylistRequest){errorNode.textContent=error.message;errorNode.hidden=false;}}finally{stylistBusy=false;if(submit.isConnected){submit.disabled=false;submit.innerHTML=`${icon('sparkle')}Подобрать образ`;}}
}
async function imageData(file) {
  if(!file) return '';
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)) throw new Error('Выберите фотографию JPEG, PNG или WebP.');
  if(file.size>3*1024*1024) throw new Error('Фотография слишком большая. Выберите файл до 3 МБ.');
  return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const image=new Image();image.onload=()=>{try{const scale=Math.min(1,1600/image.width,1600/image.height);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const context=canvas.getContext('2d');if(!context)throw new Error('Браузер не может обработать фотографию.');context.drawImage(image,0,0,canvas.width,canvas.height);const photo=canvas.toDataURL('image/webp',0.82);if(photo.length>4000000)throw new Error('Не удалось уменьшить фотографию. Выберите изображение поменьше.');resolve(photo);}catch(error){reject(error);}finally{URL.revokeObjectURL(url);}};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Не удалось открыть фотографию. Попробуйте другой файл.'));};image.src=url;});
}
function itemDialog(id='',prefill=null,shoppingId='') {
  const existing=state.items.find(item=>item.id===id);
  const item=existing || {name:prefill?.name||'',category:prefill?.category||'top',colors:prefill?.colors||[],seasons:prefill?.season?[prefill.season]:[],size:prefill?.size||'',style:prefill?.style||'',available:true,favorite:false,photo:'',warmth:'unknown',rainproof:'unknown'};
  let removePhoto=false;
  const body=`<div class="photo-upload"><div class="upload-preview" id="photo-preview">${item.photo?`<img src="${esc(item.photo)}" alt="Фотография вещи">`:icon('image')}</div><div><label class="field">Фотография <span class="optional">необязательно</span><input type="file" id="item-photo" name="photo" accept="image/jpeg,image/png,image/webp"></label><p class="footnote">JPEG, PNG или WebP, до 3 МБ. Крупное фото будет уменьшено.</p>${item.photo?'<button type="button" class="btn btn-ghost" id="remove-photo">Удалить фотографию</button>':''}</div></div><div class="form-grid"><label class="field full-width">Название *<input name="name" maxlength="100" required autofocus placeholder="Например, любимая белая рубашка" value="${esc(item.name)}"></label><label class="field">Категория *<select name="category">${Object.entries(CATEGORIES).map(([key,label])=>`<option value="${key}"${key===item.category?' selected':''}>${label}</option>`).join('')}</select></label><label class="field">Размер <span class="optional">необязательно</span><input name="size" maxlength="30" placeholder="M, 38, one size…" value="${esc(item.size)}"></label><label class="field full-width">Стиль <span class="optional">необязательно</span><input name="style" maxlength="100" placeholder="Повседневный, деловой, спортивный…" value="${esc(item.style)}"></label></div><fieldset class="field"><legend>Цвета * <span class="optional">можно несколько</span></legend><div class="color-choices">${colorCheckboxes(item.colors)}</div></fieldset><fieldset class="field"><legend>Сезоны *</legend><div class="checkbox-group">${Object.entries(SEASONS).map(([key,label])=>`<label class="checkbox-row"><input type="checkbox" name="seasons" value="${key}"${item.seasons.includes(key)?' checked':''}>${label}</label>`).join('')}</div></fieldset><details class="weather-details"><summary>Для подбора по погоде <span class="optional">необязательно</span></summary><div class="form-grid"><label class="field">Насколько тёплая вещь?<select name="warmth">${selectOptions(WARMTH_OPTIONS,item.warmth||'unknown')}</select></label><label class="field">Защита от дождя<select name="rainproof">${selectOptions(RAINPROOF_OPTIONS,item.rainproof||'unknown')}</select></label></div><p class="footnote">Если не знаете, оставьте «Не указано». Подбор предупредит, что свойства нужно проверить.</p></details><label class="checkbox-row"><input type="checkbox" name="available"${item.available?' checked':''}>Вещь готова к выходу <span class="optional">снимите отметку, если она в стирке</span></label><label class="checkbox-row"><input type="checkbox" name="favorite"${item.favorite?' checked':''}>Добавить в избранное</label>${existing?`<div class="danger-zone">${button('delete-item','Удалить вещь','btn btn-danger',existing.id,'trash')}</div>`:''}`;
  openDialog(dialog(existing?'Изменить вещь':'Новая вещь','Расскажите немного о вещи. Поля со звёздочкой обязательны.',body,'Сохранить вещь','item-form'));
  modal.querySelector('#remove-photo')?.addEventListener('click',event=>{removePhoto=true;modal.querySelector('#item-photo').value='';modal.querySelector('#photo-preview').innerHTML=icon('image');event.currentTarget.remove();});
  modal.querySelector('#item-photo').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file)return;const photo=await imageData(file);if(!event.target.isConnected)return;modal.querySelector('#photo-preview').innerHTML=`<img src="${esc(photo)}" alt="Предпросмотр фотографии">`;}catch(error){event.target.value='';formError(error);}});
  modal.querySelector('form').addEventListener('submit',event=>{event.preventDefault();runSubmission(event.currentTarget,async()=>{const form=new FormData(event.currentTarget);const colors=form.getAll('color');const seasons=form.getAll('seasons');if(!colors.length)throw new Error('Выберите хотя бы один цвет.');if(!seasons.length)throw new Error('Выберите хотя бы один сезон.');if(!String(form.get('name')).trim())throw new Error('Введите название вещи.');const file=modal.querySelector('#item-photo').files[0];const photo=file?await imageData(file):removePhoto?'':item.photo;const saved={...item,id:existing?.id||uid(),warmth:form.get('warmth'),rainproof:form.get('rainproof'),name:String(form.get('name')).trim(),category:form.get('category'),colors,seasons,size:String(form.get('size')).trim(),style:String(form.get('style')).trim(),favorite:form.has('favorite'),available:form.has('available'),photo,createdAt:existing?.createdAt||new Date().toISOString()};const next=cloneState();if(existing)next.items=next.items.map(value=>value.id===existing.id?saved:value);else next.items.push(saved);if(shoppingId)next.shoppingList=next.shoppingList.map(entry=>entry.id===shoppingId?{...entry,status:'purchased',itemId:saved.id}:entry);await commit(next,existing?'Вещь обновлена':'Вещь добавлена в гардероб');closeDialog();});});
}
function outfitDialog(id='',suggested=null,metadata={}) {
 const existing=state.outfits.find(outfit=>outfit.id===id);
 const draft={name:'',occasion:'everyday',style:'',season:'',description:'',missingItems:[],...existing,...metadata};
 const selected=suggested ?? existing?.itemIds ?? [];const missingDraft=new Map((draft.missingItems||[]).map(item=>[item.id,JSON.parse(JSON.stringify(item))]));
 function replacementOptions(category) { return `<option value="">Оставить в желаниях</option>${state.items.filter(item=>item.available&&item.category===category).map(item=>`<option value="${esc(item.id)}">${esc(item.name)}</option>`).join('')}`; }
 function missingRow(item) { return `<div class="missing-editor-row" data-missing-id="${esc(item.id)}"><div class="missing-editor-actions"><span class="missing-outfit-badge">Нужно добавить</span><button type="button" class="icon-btn" data-remove-missing="${esc(item.id)}" aria-label="Убрать недостающую вещь">${icon('close')}</button></div><div class="form-grid"><label class="field full-width">Название *<input data-missing-field="name" maxlength="100" required value="${esc(item.name)}"></label><label class="field">Категория<select data-missing-field="category">${selectOptions(CATEGORIES,item.category)}</select></label><label class="field">Размер<input data-missing-field="size" maxlength="30" value="${esc(item.size)}"></label><label class="field full-width">Зачем нужна вещь<textarea data-missing-field="reason" maxlength="500" rows="2">${esc(item.reason)}</textarea></label><label class="field full-width missing-replacement">Заменить своей вещью<select data-missing-field="replacement" name="replace-${esc(item.id)}">${replacementOptions(item.category)}</select></label></div><button type="button" class="btn btn-secondary" data-shop-editor-missing="${esc(item.id)}">${icon('shopping')}В покупки</button></div>`; }
 const body=`<label class="field">Название образа *<input name="name" maxlength="100" required autofocus placeholder="Например, прогулка по городу" value="${esc(draft.name)}"></label><div class="form-grid"><label class="field">Повод<select name="occasion">${selectOptions(OCCASIONS,draft.occasion)}</select></label><label class="field">Стиль<select name="style"><option value="">Не указан</option>${selectOptions(Object.fromEntries(Object.entries(STYLE_OPTIONS).filter(([key])=>key!=='any')),draft.style)}</select></label><label class="field">Сезон<select name="season"><option value="">Любой сезон</option>${selectOptions(SEASONS,draft.season)}</select></label><label class="field full-width">Описание <span class="optional">необязательно</span><textarea name="description" maxlength="500" rows="2" placeholder="Детали, настроение или заметка к образу">${esc(draft.description)}</textarea></label></div><div class="selection-summary"><span id="selection-count">Выбрано: ${selected.filter(id=>state.items.some(item=>item.id===id)).length}</span><span class="optional">до 30 деталей</span></div>${existing&&outfitStatus(existing,state.items).missing.length?'<p class="notice">Удалённые вещи будут убраны из состава при сохранении.</p>':''}${suggested?'<p class="notice">Меняйте состав по своему вкусу. Недостающие детали отмечены отдельно.</p>':''}${state.items.length?`<fieldset class="field"><legend>Ваши вещи</legend><div class="choice-grid">${state.items.map(item=>`<label class="choice-card${!item.available?' is-unavailable':''}"><input type="checkbox" name="itemIds" value="${esc(item.id)}"${selected.includes(item.id)?' checked':''}${!item.available&&!selected.includes(item.id)?' disabled':''}><div class="choice-image">${itemPicture(item)}</div><strong>${esc(item.name)}</strong><span class="item-meta">${!item.available?'В стирке':esc(CATEGORIES[item.category])}</span></label>`).join('')}</div></fieldset>`:'<p class="notice">В гардеробе пока нет вещей. Можно сохранить идею с недостающими деталями.</p>'}<section class="missing-editor"><h3>Чего не хватает?</h3><p class="footnote">Добавьте желание или замените его своей вещью той же категории. Изменения сохранятся вместе с образом.</p><div id="missing-editor-rows">${[...missingDraft.values()].map(missingRow).join('')}</div><button type="button" class="btn btn-secondary" id="add-missing-editor">${icon('plus')}Добавить недостающую вещь</button></section><label class="checkbox-row"><input type="checkbox" name="favorite"${draft.favorite?' checked':''}>Добавить в избранное</label>${existing?`<div class="danger-zone">${button('copy-outfit','Создать копию','btn btn-secondary',existing.id,'copy')}${button('delete-outfit','Удалить образ','btn btn-danger',existing.id,'trash')}</div>`:''}`;
 openDialog(dialog(existing?'Изменить образ':'Собрать образ','Соберите готовый образ или сохраните идею на будущее.',body,'Сохранить образ','outfit-form'));
 const form=modal.querySelector('form');const rows=form.querySelector('#missing-editor-rows');
 function updateCount() { const selectedIds=[...form.querySelectorAll('[name="itemIds"]:checked')].map(input=>input.value);rows.querySelectorAll('[data-missing-field="replacement"]').forEach(input=>{if(input.value)selectedIds.push(input.value);});form.querySelector('#selection-count').textContent=`Ваших вещей: ${new Set(selectedIds).size}`;for(const row of rows.children){const replaced=!!row.querySelector('[data-missing-field="replacement"]').value;row.querySelector('[data-shop-editor-missing]').disabled=replaced;row.querySelector('[data-missing-field="name"]').required=!replaced;} }
 form.querySelectorAll('[name="itemIds"]').forEach(input=>input.addEventListener('change',updateCount));
 form.querySelector('#add-missing-editor').addEventListener('click',()=>{if(rows.children.length>=10){formError(new Error('В одном образе может быть до 10 недостающих деталей.'));return;}const item={id:uid(),name:'Новая вещь',category:'top',colors:[],season:form.querySelector('[name="season"]').value,style:form.querySelector('[name="style"]').value,size:'',reason:''};missingDraft.set(item.id,item);rows.insertAdjacentHTML('beforeend',missingRow(item));rows.lastElementChild.querySelector('input').focus();});
 rows.addEventListener('click',event=>{const remove=event.target.closest('[data-remove-missing]');if(remove){event.stopPropagation();remove.closest('.missing-editor-row').remove();updateCount();return;}const shop=event.target.closest('[data-shop-editor-missing]');if(!shop)return;event.stopPropagation();try{const current=collectDraft();const missing=current.missingItems.find(item=>item.id===shop.dataset.shopEditorMissing);if(!missing)return;if(!missing.name.trim())throw new Error('Введите название недостающей вещи.');const focus=previousFocus;shoppingDialog('',shoppingDraftFromMissing(missing),()=>{outfitDialog(id,current.itemIds,current);previousFocus=focus;});}catch(error){formError(error);}});
 rows.addEventListener('change',event=>{const row=event.target.closest('.missing-editor-row');if(!row)return;if(event.target.dataset.missingField==='category')row.querySelector('[data-missing-field="replacement"]').innerHTML=replacementOptions(event.target.value);updateCount();});
 function collectDraft() {
  const data=new FormData(form);const itemIds=data.getAll('itemIds');const missingItems=[];
  for(const row of rows.children){const original=missingDraft.get(row.dataset.missingId);const category=row.querySelector('[data-missing-field="category"]').value;const replacement=row.querySelector('[data-missing-field="replacement"]').value;if(replacement)itemIds.push(replacement);else missingItems.push({...original,name:row.querySelector('[data-missing-field="name"]').value.trim(),category,size:row.querySelector('[data-missing-field="size"]').value.trim(),reason:row.querySelector('[data-missing-field="reason"]').value.trim()});}
  return {...draft,name:String(data.get('name')),itemIds:[...new Set(itemIds)],missingItems,occasion:data.get('occasion'),style:data.get('style'),season:data.get('season'),description:String(data.get('description')),favorite:data.has('favorite')};
 }
 form.addEventListener('submit',event=>{event.preventDefault();runSubmission(form,async()=>{
  const data=new FormData(form);const itemIds=data.getAll('itemIds');const missingItems=[];
  for(const row of rows.children){const original=missingDraft.get(row.dataset.missingId);const category=row.querySelector('[data-missing-field="category"]').value;const replacement=row.querySelector('[data-missing-field="replacement"]').value;if(replacement){const item=state.items.find(item=>item.id===replacement&&item.available&&item.category===category);if(!item)throw new Error('Выберите доступную вещь той же категории для замены.');itemIds.push(item.id);}else{const name=row.querySelector('[data-missing-field="name"]').value.trim();if(!name)throw new Error('Введите название недостающей вещи.');missingItems.push({...original,name,category,size:row.querySelector('[data-missing-field="size"]').value.trim(),reason:row.querySelector('[data-missing-field="reason"]').value.trim()});}}
  const uniqueIds=[...new Set(itemIds)];if(!uniqueIds.length&&!missingItems.length)throw new Error('Выберите хотя бы одну вещь или добавьте недостающую деталь.');if(uniqueIds.length+missingItems.length>30)throw new Error('В одном образе может быть не больше 30 деталей.');
  const name=String(data.get('name')).trim();if(!name)throw new Error('Введите название образа.');const saved={...draft,id:existing?.id||uid(),name,itemIds:uniqueIds,missingItems,occasion:data.get('occasion'),style:data.get('style'),season:data.get('season'),description:String(data.get('description')).trim(),favorite:data.has('favorite'),createdAt:existing?.createdAt||new Date().toISOString()};const next=cloneState();if(existing)next.outfits=next.outfits.map(value=>value.id===existing.id?saved:value);else next.outfits.push(saved);await commit(next,existing?'Образ обновлён':'Образ сохранён');closeDialog();
 });});
}
function suggestionDialog() { changePage('stylist'); }
function planDialog(id='',outfitId='',slot='day') {
 const existing=state.plans.find(plan=>plan.id===id);
 if(!state.outfits.length){toast('Сначала сохраните хотя бы один образ.');changePage('outfits');return;}
 const body=`<div class="form-grid"><label class="field">Дата *<input type="date" name="date" required min="1900-01-01" max="2200-12-31" value="${esc(existing?.date || selectedDate)}"></label><label class="field">Время дня<select name="slot">${Object.entries(SLOTS).map(([key,label])=>`<option value="${key}"${key===(existing?.slot || slot)?' selected':''}>${label}</option>`).join('')}</select></label><label class="field full-width">Образ *<select name="outfitId" required>${state.outfits.map(outfit=>`<option value="${esc(outfit.id)}"${outfit.id===(existing?.outfitId || outfitId)?' selected':''}>${esc(outfit.name)}${outfitStatus(outfit,state.items).complete?'':' — проверьте состав'}</option>`).join('')}</select></label></div><p class="footnote">На день можно назначить один дневной и один вечерний образ. Существующий план на выбранное время будет заменён.</p>`;
 openDialog(dialog(existing?'Изменить план':'Запланировать образ','Завтрашнее утро начинается сегодня.',body,'Сохранить план','plan-form'));
 modal.querySelector('form').addEventListener('submit',event=>{event.preventDefault();runSubmission(event.currentTarget,async()=>{const form=new FormData(event.currentTarget);const date=form.get('date');if(!validDate(date))throw new Error('Выберите корректную дату.');const saved={id:existing?.id||uid(),date,slot:form.get('slot'),outfitId:form.get('outfitId')};const next=cloneState();next.plans=next.plans.filter(plan=>plan.id!==saved.id && !(plan.date===saved.date&&plan.slot===saved.slot));next.plans.push(saved);selectedDate=date;displayedMonth=new Date(`${date.slice(0,7)}-01T12:00:00`);await commit(next,'Образ добавлен в календарь');closeDialog();});});
}
function exportBackup() {
 const data=JSON.stringify(state,null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`MyCloset-backup-${localDate()}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия подготовлена к скачиванию.');
}
function importDialog() {
 openDialog(dialog('Загрузить резервную копию','Выберите JSON-файл, ранее сохранённый в MyCloset.',`<label class="field">Файл резервной копии *<input type="file" name="backup" accept=".json,application/json" required></label><p class="notice">Импорт полностью заменит текущий гардероб, образы, покупки, планы и профиль. При необходимости сначала скачайте текущую копию.</p><label class="checkbox-row"><input type="checkbox" name="confirm" required>Подтверждаю замену текущих данных</label>`,'Заменить данные','import-form'));
 modal.querySelector('form').addEventListener('submit',event=>{event.preventDefault();runSubmission(event.currentTarget,async()=>{const file=modal.querySelector('[name="backup"]').files[0];if(!file)throw new Error('Выберите файл.');if(file.size>MAX_BACKUP_FILE_BYTES)throw new Error(`Файл слишком большой. Максимальный размер — ${Math.floor(MAX_BACKUP_FILE_BYTES/1024/1024)} МиБ.`);let parsed;try{parsed=JSON.parse(await file.text());}catch{throw new Error('Не удалось прочитать JSON. Выберите корректную резервную копию MyCloset.');}const imported=validateState(parsed);await commit(imported,'Резервная копия загружена');closeDialog();});});
}
async function handleAction(action,target) {
 const id=target.dataset.id;
 if(action==='close-dialog'){closeDialog();return;}
 if(action==='open-more'){moreDialog();return;}
 if(action==='new-shopping'){shoppingDialog();return;}
 if(action==='edit-shopping'){shoppingDialog(id);return;}
 if(action==='shopping-filter'){if(['planned','purchased','all'].includes(id)){shoppingFilter=id;render();}return;}
 if(action==='shop-missing-outfit'||action==='shop-missing-recommendation'){const outfit=action==='shop-missing-outfit'?state.outfits.find(outfit=>outfit.id===id):stylistResult?.outfits[Number(id)];const missing=outfit?.missingItems?.find(item=>item.id===target.dataset.missingId);if(missing)shoppingDialog('',shoppingDraftFromMissing(missing));return;}
 if(action==='purchase-shopping'||action==='reopen-shopping'){const next=cloneState();const item=next.shoppingList.find(item=>item.id===id);if(!item)return;const status=action==='purchase-shopping'?'purchased':'planned';if(status==='planned'&&shoppingDuplicate({...item,status},id))throw new Error('Такая вещь уже есть в планах покупок. Измените её название или детали.');item.status=status;if(status==='planned')item.itemId='';await commit(next,status==='purchased'?'Покупка отмечена':'Снова в планах');return;}
 if(action==='delete-shopping'){const item=state.shoppingList.find(item=>item.id===id);if(!item)return;confirmDialog('Удалить желание?',`«${item.name}» будет удалено из списка покупок.`,async()=>{const next=cloneState();next.shoppingList=next.shoppingList.filter(item=>item.id!==id);await commit(next,'Желание удалено');});return;}
 if(action==='shopping-to-wardrobe'){const item=state.shoppingList.find(item=>item.id===id);if(!item)return;if(item.itemId&&state.items.some(garment=>garment.id===item.itemId)){toast('Эта покупка уже есть в гардеробе.');return;}itemDialog('',item,item.id);return;}
 if(action==='add-item'){itemDialog();return;}
 if(action==='edit-item'){itemDialog(id);return;}
 if(action==='new-outfit'){outfitDialog();return;}
 if(action==='edit-outfit'){outfitDialog(id);return;}
 if(action==='suggest'){suggestionDialog();return;}
 if(action==='choose-city'){cityDialog();return;}
 if(action==='refresh-weather'){await hydrateWeather(true);return;}
 if(action==='stylist-date'){stylistCriteria.date=selectedDate;invalidateStylist();changePage('stylist');return;}
 if(action==='rerun-stylist'){await runStylist(true);return;}
 if(action==='save-recommendation'){const recommendation=stylistResult?.outfits[Number(id)];if(!recommendation)return;outfitDialog('',recommendation.itemIds,{name:recommendation.title,description:recommendation.description,occasion:stylistCriteria.occasion,style:stylistCriteria.style==='any'?'':stylistCriteria.style,season:stylistCriteria.season,missingItems:recommendation.missingItems||[]});return;}
 if(action==='copy-outfit'){const original=state.outfits.find(outfit=>outfit.id===id);if(!original)return;outfitDialog('',original.itemIds,{...original,id:undefined,name:`${original.name.slice(0,90)} — копия`,favorite:false,createdAt:undefined});return;}
 if(action==='plan-outfit'){planDialog('',id);return;}
 if(action==='add-plan'){planDialog('','',target.dataset.slot || 'day');return;}
 if(action==='edit-plan'){planDialog(id);return;}
 if(action==='delete-plan'){const next=cloneState();next.plans=next.plans.filter(plan=>plan.id!==id);await commit(next,'План убран из календаря');return;}
 if(action==='favorite-item'||action==='toggle-available'){const next=cloneState();const item=next.items.find(item=>item.id===id);if(!item)return;const field=action==='favorite-item'?'favorite':'available';item[field]=!item[field];await commit(next,field==='favorite'?(item.favorite?'Вещь добавлена в избранное':'Вещь убрана из избранного'):(item.available?'Вещь снова готова к выходу':'Вещь отправлена в стирку'));return;}
 if(action==='favorite-outfit'){const next=cloneState();const outfit=next.outfits.find(outfit=>outfit.id===id);if(!outfit)return;outfit.favorite=!outfit.favorite;await commit(next,outfit.favorite?'Образ добавлен в избранное':'Образ убран из избранного');return;}
 if(action==='delete-item'){const item=state.items.find(item=>item.id===id);if(!item)return;const used=state.outfits.filter(outfit=>outfit.itemIds.includes(id)).length;confirmDialog('Удалить вещь?',`«${item.name}» будет удалена.${used?' Она входит в сохранённые образы: они останутся, но будут отмечены как неполные.':''}`,async()=>{const next=cloneState();next.items=next.items.filter(item=>item.id!==id);next.shoppingList=next.shoppingList.map(entry=>entry.itemId===id?{...entry,itemId:''}:entry);await commit(next,'Вещь удалена');});return;}
 if(action==='delete-outfit'){const outfit=state.outfits.find(outfit=>outfit.id===id);if(!outfit)return;const plans=state.plans.filter(plan=>plan.outfitId===id).length;confirmDialog('Удалить образ?',`«${outfit.name}» будет удалён.${plans?' Его планы также будут убраны из календаря.':''}`,async()=>{const next=cloneState();next.outfits=next.outfits.filter(outfit=>outfit.id!==id);next.plans=next.plans.filter(plan=>plan.outfitId!==id);await commit(next,'Образ удалён');});return;}
 if(action==='reset-filters'){filters={query:'',category:'',color:'',season:'',availability:''};render();return;}
 if(action==='prev-month'||action==='next-month'){displayedMonth=new Date(displayedMonth.getFullYear(),displayedMonth.getMonth()+(action==='next-month'?1:-1),1);render();return;}
 if(action==='today'){selectedDate=localDate();displayedMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);render();return;}
 if(action==='select-date'){selectedDate=target.dataset.date;render();return;}
 if(action==='export'){exportBackup();return;}
 if(action==='import'){importDialog();return;}
 if(action==='demo'){confirmDialog('Добавить учебные вещи?','Добавим 6 примеров вещей без фотографий и один образ, чтобы вы могли проверить возможности MyCloset. Их можно изменить или удалить.',async()=>{await commit(demoState(state),'Учебные вещи добавлены');},'Добавить примеры');return;}
 if(action==='reset'){confirmDialog('Удалить все данные?','Все ваши вещи, фотографии, образы, покупки, планы и профиль в этом браузере будут удалены. Сохраните резервную копию, если хотите восстановить их позже.',async()=>{await reopenForReset();await commit(emptyState(),storageMode==='persistent'?'Все данные удалены':'Данные текущего сеанса удалены');filters={query:'',category:'',color:'',season:'',availability:''};},'Удалить всё');}
}

document.addEventListener('click',event=>{
 if(storageMode==='loading' && event.target.closest('[data-nav], [data-action], #add-item')) { event.preventDefault(); toast('Подождите, открываем ваш гардероб.'); return; }
 const nav=event.target.closest('[data-nav]');if(nav){event.preventDefault();changePage(nav.dataset.nav);return;}
 const target=event.target.closest('[data-action], #add-item');if(!target)return;
 const action=target.id==='add-item'?'add-item':target.dataset.action;
 handleAction(action,target).catch(error=>{if(modal.open)formError(error);else toast(error.message || 'Не удалось выполнить действие.',true);});
});
main.addEventListener('input',event=>{const key=event.target.dataset.filter;if(!key)return;filters[key]=event.target.value;if(event.target.type==='search'){clearTimeout(searchTimer);searchTimer=setTimeout(render,180);}});
main.addEventListener('change',event=>{const key=event.target.dataset.filter;if(!key)return;filters[key]=event.target.value;render();});
main.addEventListener('input',event=>{const form=event.target.closest('#stylist-form');if(!form)return;readStylistCriteria(form);invalidateStylist();});
main.addEventListener('change',event=>{const form=event.target.closest('#stylist-form');if(!form)return;readStylistCriteria(form);invalidateStylist();if(event.target.name==='weatherMode'||event.target.name==='date'){form.querySelector('#stylist-weather-panel').innerHTML=stylistWeatherPanel();hydrateWeather();}});
main.addEventListener('submit',event=>{if(event.target.id!=='stylist-form')return;event.preventDefault();runStylist();});
main.addEventListener('submit',event=>{if(event.target.id!=='profile-form')return;event.preventDefault();runSubmission(event.target,async()=>{const form=new FormData(event.target);const next=cloneState();next.profile={...next.profile,name:String(form.get('name')).trim(),city:String(form.get('city')).trim(),location:String(form.get('city')).trim()===state.profile.city?state.profile.location:null,styles:String(form.get('styles')).trim(),colors:form.getAll('colors')};await commit(next,'Профиль сохранён');});});

main.innerHTML='<div class="loading-state" role="status">Открываем ваш гардероб…</div>';
await initializeStorage();
render();




